1. /*
2. Copyright 2026 Element Creations Ltd.
3. 
4. SPDX-License-Identifier: AGPL-3.0-only OR LicenseRef-Element-Commercial
5. Please see LICENSE files in the repository root for full details.
6. */
7. 
8. import { defineConfig, type ViteUserConfig } from "vitest/config";
9. import { type Reporter } from "vitest/reporters";
10. import { env } from "process";
11. 
12. const reporters: ViteUserConfig["test"]["reporters"] = [["default"]];
13. 
14. const slowTestReporter: Reporter = {
15.     onTestRunEnd(testModules, unhandledErrors, reason) {
16.         const tests = testModules
17.             .flatMap((m) => Array.from(m.children.allTests()))
18.             .filter((test) => test.diagnostic()?.slow);
19.         tests.sort((x, y) => x.diagnostic()?.duration! - y.diagnostic()?.duration!);
20.         tests.reverse();
21. 
22.         if (tests.length > 0) {
23.             console.warn("Slowest 10 tests:");
24.         }
25.         for (const t of tests.slice(0, 10)) {
26.             console.warn(`${t.module.moduleId} > ${t.fullName}: ${t.diagnostic()?.duration.toFixed(0)}ms`);
27.         }
28.     },
29. };
30. 
31. // if we're running under GHA, enable the GHA & Sonar reporters
32. if (env["GITHUB_ACTIONS"] !== undefined) {
33.     reporters.push(["github-actions", { silent: false }]);
34.     reporters.push([
35.         "vitest-sonar-reporter",
36.         {
37.             outputFile: process.env.SHARD
38.                 ? `coverage/sonar-report-${process.env.SHARD}.xml`
39.                 : "coverage/sonar-report.xml",
40.         },
41.     ]);
42. 
43.     // if we're running against the develop branch, also enable the slow test reporter
44.     if (env["GITHUB_REF"] == "refs/heads/develop") {
45.         reporters.push(slowTestReporter);
46.     }
47. }
48. 
49. export default defineConfig({
50.     test: {
51.         coverage: {
52.             provider: "v8",
53.             include: ["src/**/*"],
54.             reporter: "lcov",
55.         },
56.         environment: "node",
57.         reporters,
58.         setupFiles: "spec/setupTests.ts",
59.         globals: true,
60.         pool: "threads",
61.     },
62. });
63.

